-- Layer 4+: semantic search for the knowledge engine.
-- Adds pgvector, an embedding column (gte-small = 384 dims), an HNSW index,
-- and a cosine-similarity match function. Embeddings are generated by the
-- `embed` Edge Function and stored from the Next.js knowledge routes.

CREATE EXTENSION IF NOT EXISTS vector;

ALTER TABLE knowledge_articles ADD COLUMN IF NOT EXISTS embedding vector(384);

CREATE INDEX IF NOT EXISTS idx_knowledge_embedding
    ON knowledge_articles USING hnsw (embedding vector_cosine_ops);

-- Cosine-similarity match. Published only, threshold-filtered, optional case-type filter.
CREATE OR REPLACE FUNCTION match_knowledge_articles(
    query_embedding vector(384),
    match_threshold float,
    match_count int,
    filter_case_type text DEFAULT NULL
)
RETURNS TABLE (
    id uuid,
    title text,
    content text,
    category text,
    tags text[],
    case_types text[],
    similarity float
)
LANGUAGE sql STABLE AS $$
    SELECT
        ka.id, ka.title, ka.content, ka.category, ka.tags, ka.case_types,
        1 - (ka.embedding <=> query_embedding) AS similarity
    FROM knowledge_articles ka
    WHERE ka.status = 'published'
      AND ka.embedding IS NOT NULL
      AND 1 - (ka.embedding <=> query_embedding) > match_threshold
      AND (filter_case_type IS NULL OR filter_case_type = ANY(ka.case_types))
    ORDER BY ka.embedding <=> query_embedding
    LIMIT match_count;
$$;
